# Create Chen Cortical Atlases
#
# The Chen atlases are the LCBC internal cortical thickness and area
# parcellations. Both are built from .annot files generated by
# data-raw/create_annots.R out of the original gclust ROI geometry.
#
# Reference: Chen CH, et al. (2012). Genetic topography of brain
#   morphology. PNAS, 109(44):18010-18015.
#   doi:10.1073/pnas.1210903109 # nolint: commented_code_linter.
#
# Run with: Rscript data-raw/make_atlas.R

library(ggseg.extra)
library(ggseg.formats)

Sys.setenv(FREESURFER_HOME = "/Applications/freesurfer/7.4.1")

annot_dir <- here::here("data-raw", "fsaverage5")

build_chen_atlas <- function(atlas_type, atlas_name) {
  annot_files <- file.path(
    annot_dir,
    sprintf(c("lh.gclust_%s.annot", "rh.gclust_%s.annot"), atlas_type)
  )
  missing <- annot_files[!file.exists(annot_files)]
  if (length(missing) > 0) {
    cli::cli_abort(c(
      "Missing {atlas_type} annotation{?s}: {.file {basename(missing)}}.",
      i = "Run {.file data-raw/create_annots.R} first."
    ))
  }
  create_cortical_from_annotation(
    input_annot = annot_files,
    atlas_name = atlas_name,
    output_dir = "data-raw",
    skip_existing = TRUE,
    cleanup = FALSE
  ) |>
    atlas_region_contextual("unknown|Unknown", "label")
}

.chenAr <- build_chen_atlas("area", "chenAr")
.chenTh <- build_chen_atlas("thickness", "chenTh")

print(.chenAr)
print(.chenTh)

usethis::use_data(
  .chenAr,
  .chenTh,
  overwrite = TRUE,
  compress = "xz",
  internal = TRUE
)
